test("Color deserialization fail", () => {
  const jsonable = "invalid-literal";

  const literalOrError = OurJsonization.colorFromJsonable(
    jsonable
  );

  expect(literalOrError.error.message).toStrictEqual(
    "Not a valid string representation of a literal of Color: invalid-literal"
  );
});

